package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class AssetState(val loading:Boolean=false,val query:String="",val status:String?=null,val rows:List<JsonObject> = emptyList(),val options:JsonObject=buildJsonObject{},val detail:JsonObject?=null,val editing:JsonObject?=null,val error:String?=null)
class AccountAssetViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(AssetState());val state:StateFlow<AssetState> = _state;init{load()};fun load()=viewModelScope.launch{try{_state.value=_state.value.copy(loading=true,error=null,options=api.assetOptions(),rows=api.assets(_state.value.query,_state.value.status).map{it.jsonObject});_state.value=_state.value.copy(loading=false)}catch(e:Exception){fail(e)}};fun search(q:String){_state.value=_state.value.copy(query=q);load()};fun filter(s:String?){_state.value=_state.value.copy(status=s);load()};fun create(){_state.value=_state.value.copy(editing=buildJsonObject{})};fun edit(){_state.value=_state.value.copy(editing=_state.value.detail?.get("asset")?.jsonObject)};fun close(){_state.value=_state.value.copy(detail=null,editing=null)};fun open(id:String)=viewModelScope.launch{try{_state.value=_state.value.copy(detail=api.asset(id))}catch(e:Exception){fail(e)}};fun save(p:JsonObject)=viewModelScope.launch{try{val id=_state.value.editing?.get("id")?.jsonPrimitive?.contentOrNull;val x=api.saveAsset(id,p);_state.value=_state.value.copy(editing=null,detail=api.asset(x["id"]!!.jsonPrimitive.content));load()}catch(e:Exception){fail(e)}};fun action(id:String,p:JsonObject)=viewModelScope.launch{try{api.assetAction(id,p);_state.value=_state.value.copy(detail=api.asset(id));load()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,error=if(e is IOException)"Offline. No asset action was confirmed." else "Asset action rejected by server.")}}
